import {hero,visibleLots,STAT_LABELS,canBid,TEAM_LINKS,synergy} from './engine.mjs';
export function auctionLots(game,portrait){
  return `<section class="pool-section"><div class="section-line"><h2>AÇILAN KAHRAMANLAR</h2><span class="muted">${Math.min(game.round,10)} / 10 tamamlandı</span></div><div class="pool">${visibleLots(game).map(({id,index:i})=>{
    if(!id)return `<div class="pool-card sealed" aria-label="${i+1}. karakter gizli"><span class="pool-number">${String(i+1).padStart(2,'0')}</span><span class="sealed-emblem">N</span><strong>GİZLİ</strong><span class="pool-type">Sırası gelince açılır</span></div>`;
    const x=hero(id),lot=game.history.find(t=>t.id===id&&!t.reinforcement);
    return `<button class="pool-card ${i===game.round&&game.phase==='auction'?'current':''} ${i<game.round?'sold':''}" data-action="detail" data-id="${id}">${portrait(x)}<div class="pool-shade"></div><span class="pool-number">${String(i+1).padStart(2,'0')}</span>${lot?`<span class="owner-marker ${lot.winner===null?'unsold':'p'+lot.winner}">${lot.winner===null?'PAS':`P${lot.winner+1} · ${lot.price} ◈`}</span>`:i===game.round&&game.phase==='auction'?'<span class="current-marker">ŞİMDİ</span>':''}<strong>${x.name}</strong><span class="pool-type">${x.type}</span></button>`;
  }).join('')}</div><p class="sealed-note">Sıradaki kahramanlar gizli. Her karakter yalnızca kendi açık artırması başladığında açılır.</p></section>`;
}

export function auctionShow(game,{portrait,esc,icon,playerPanel,ready,selectedBid,botTurn=false,room=null,reveal=false}){
 if(game.phase==='ready')return `<main><section class="intro"><div><div class="eyebrow">AÇIK ARTIRMA TAMAMLANDI</div><h1>Takımlar hazır.<br><em>Sıra arenada.</em></h1></div><button class="outline" data-action="setup">Yeni oyun</button></section>${ready()}${auctionLots(game,portrait)}</main>`;
 const h=hero(game.pool[game.round]),p=game.players[game.turn],min=game.bid+1;
 const canAct=!botTurn&&(!room||room.side===game.turn&&room.connected&&!room.pending&&room.slots.every(s=>s?.connected));
 const eligible=canAct&&canBid(game,game.turn,selectedBid);
 const entries=(room?.auctionBids||game.auctionBids||[]).filter(e=>e.round===game.round).slice(-5).reverse();
 const link=TEAM_LINKS.find(l=>l.members.includes(h.id)&&l.members.some(id=>id!==h.id&&p.team.includes(id)));
 const last=game.history.filter(l=>!l.reinforcement).at(-1);
 return `<main class="auction-page"><section class="auction-intro"><div><div class="eyebrow"><span class="live-dot"></span> KAHRAMAN MÜZAYEDESİ</div><h1>Teklif yükselir.<br><em>Rekabet başlar.</em></h1><p>20 coin ile doğru kahramanı yakala. Bir sonraki kart sürpriz.</p></div><div class="auction-mode"><span>${room?'İKİ CİHAZ · CANLI ODA':game.mode==='bot'?'SEN + BOT':'AYNI CİHAZ · İKİ OYUNCU'}</span>${!room?`<button class="outline small" data-action="online">Arkadaşını davet et ↗</button><button class="text-button" data-action="setup">Yeni oyun</button>`:''}</div></section>
 ${last?`<div class="auction-win-banner"><span>${last.winner===null?'LOT GEÇİLDİ':'SATILDI ✓'}</span><b>${esc(hero(last.id).name)}</b><span>${last.winner===null?'Teklif verilmedi.':`${esc(game.players[last.winner].name)} · ${last.price} coin`}</span></div>`:''}
 <div class="auction-layout"><section class="auction-stage auction-duel ${reveal?'is-reveal':''}" style="--hero-color:${h.color}"><div class="auction-live-head"><span><i class="live-dot"></i> CANLI TEKLİF</span><b>LOT ${String(game.round+1).padStart(2,'0')} <small>/ 10</small></b><div class="auction-clock ${room?'has-clock':''}" role="timer" aria-label="Teklif için kalan süre"><span id="auction-seconds">${room?'20':'∞'}</span><small>${room?'SANİYE':'SÜRESİZ'}</small></div></div>
 <div class="auction-pressure"><i id="auction-time-fill"></i></div><div class="hero-feature"><div class="feature-art">${portrait(h)}<div class="art-shade"></div><div class="hero-reveal-flare"></div><div class="art-top"><span class="rarity">${icon('star')} ${h.rating>=75?'EFSANEVİ':h.rating>=65?'DESTANSI':'KAHRAMAN'}</span><button class="glass-button" data-action="detail" data-id="${h.id}" aria-label="Karakter detayları">↗</button></div><div class="art-caption"><span>${h.group.toUpperCase()} · ${h.type.toUpperCase()}</span><h2>${h.name}</h2><p>${h.alias}</p></div><div class="art-number">${String(game.round+1).padStart(2,'0')}</div></div><div class="feature-info"><div class="feature-heading"><div class="eyebrow">ŞİMDİ SAHNEDE</div><div class="rating"><strong>${h.rating}</strong><span>GENEL<br>PUAN</span></div></div><p class="hero-quote">“${h.quote}”</p><div class="stats">${h.stats.map((v,i)=>`<div class="stat"><span>${STAT_LABELS[i]}</span><div class="stat-track"><i style="width:${v*10}%"></i></div><b>${v}<small>/10</small></b></div>`).join('')}</div><div class="skill"><span class="skill-icon">${icon('bolt')}</span><div><b>${h.skill}</b><p>${h.desc}</p></div></div><div class="auction-fit">${link?`<strong>✦ İKİLİ HAMLE TAMAMLANIR</strong><span>${esc(link.name)} · ${link.members.filter(id=>id!==h.id).map(id=>hero(id).name).join(', ')}</span>`:`<strong>TAKIMINA ETKİSİ</strong><span>${p.team.length>=5?'Takımın dolu. Bu lotta pas geç.':`Grup uyumu: +%${synergy([...p.team,h.id])} · ${p.team.length+1}/5 kahraman`}</span>`}</div></div></div>
 <div class="auction-bid-board"><div class="auction-high-bid"><span>EN YÜKSEK TEKLİF</span><strong>${game.bid||'—'} <small>◈</small></strong><b>${game.leader===null?'Açılışı kim yapacak?':esc(game.players[game.leader].name)+' önde'}</b></div><div class="auction-bid-history" aria-live="polite"><span>TEKLİF AKIŞI</span>${entries.length?entries.map(e=>`<div class="bid-tick side-${e.side}"><i></i><b>${esc(game.players[e.side].name)}</b><strong>${e.type==='bid'?e.amount+' ◈':e.type==='timeout'?'SÜRE DOLDU':'PAS'}</strong></div>`).join(''):'<p>İlk teklif bekleniyor.<br>Bütçeni rakibinle yarıştır.</p>'}</div></div>
 <div class="bidding-console"><div class="whose-turn"><span class="turn-avatar p${game.turn}">${game.turn+1}</span><div><b>${botTurn?'Bot düşünüyor…':room&&room.side!==game.turn?`${esc(p.name)} teklifini düşünüyor…`:`${esc(p.name)}, sahne senin.`}</b><span>${p.team.length>=5?'Takımın dolu; pas geç.':p.coins<min?'Yeni teklif için bütçen yetmiyor; pas geç.':`${p.coins} coin bütçe · En az ${min} coin`}</span></div></div><div class="bid-controls"><div class="stepper"><button data-action="minus" aria-label="Teklifi azalt" ${selectedBid<=min||!canAct?'disabled':''}>−</button><span>${selectedBid} ◈</span><button data-action="plus" aria-label="Teklifi artır" ${selectedBid>=p.coins||!canAct?'disabled':''}>+</button></div><button class="primary" data-action="bid" ${eligible?'':'disabled'}>${selectedBid} coin teklif ver ${icon('arrow')}</button><button class="pass-button" data-action="pass" ${canAct?'':'disabled'}>${game.leader===null?'Pas geç':'Rakibine bırak'}</button></div><div class="auction-quick-bids"><span>HIZLI TEKLİF</span>${[1,3,5].map(n=>`<button data-action="quick-bid" data-id="${game.bid+n}" ${canAct&&canBid(game,game.turn,game.bid+n)?'':'disabled'}>${game.bid+n} ◈ <small>+${n}</small></button>`).join('')}<small>Yalnızca kazananın teklifi ödenir.</small></div></div></section><aside class="players">${game.players.map((p,i)=>playerPanel(p,i)).join('')}<div class="auction-strategy"><b>BİR SONRAKİ KART?</b><span>Kimse bilmiyor. Gücünü şimdi mi kullanacaksın, coin’ini sonraya mı saklayacaksın?</span>${room?'<small>20 saniye dolunca otomatik pas. Bağlantı koparsa saat durur.</small>':''}</div></aside></div>${auctionLots(game,portrait)}</main>`;
}
